import React from 'react'
import ReactDOM from 'react-dom/client'
import { Auth0Provider } from '@auth0/auth0-react'
import { I18nextProvider } from 'react-i18next'
import posthog from 'posthog-js'
import i18n from './i18n/index.js'
import AppWebsite from './App.jsx'
import AppPlatform from './AppPlatform.jsx'
import './index.css'

// PWA service worker (generated by vite-plugin-pwa): app shell + models +
// fonts precached, API reads NetworkFirst, chat posts replay on reconnect.
if ('serviceWorker' in navigator && import.meta.env.PROD) {
  import('virtual:pwa-register').then(({ registerSW }) => {
    registerSW({ immediate: true })
  }).catch(() => {})
}

const App = import.meta.env.MODE === 'platform' ? AppPlatform : AppWebsite

if (import.meta.env.VITE_POSTHOG_KEY) {
  posthog.init(import.meta.env.VITE_POSTHOG_KEY, {
    api_host: import.meta.env.VITE_POSTHOG_HOST ?? 'https://us.i.posthog.com',
    capture_pageview: true,
  })
}

const auth0Domain = import.meta.env.VITE_AUTH0_DOMAIN
const auth0ClientId = import.meta.env.VITE_AUTH0_CLIENT_ID

const root = (
  <React.StrictMode>
    <I18nextProvider i18n={i18n}>
      {auth0Domain && auth0ClientId ? (
        <Auth0Provider
          domain={auth0Domain}
          clientId={auth0ClientId}
          authorizationParams={{
            redirect_uri: window.location.origin,
            audience: 'https://api.kev.sansmercantile.com',
          }}
        >
          <App />
        </Auth0Provider>
      ) : (
        <App />
      )}
    </I18nextProvider>
  </React.StrictMode>
)

ReactDOM.createRoot(document.getElementById('root')).render(root)
